declare items jsonb := '[{"id":"7539be09-5d4c-4bbd-8ca9-91123f07f800","slug":"sd-tambahan-alat-sekolah","grade":"SD","aspect":"kosakata","title":"Benda di tas sekolah","data":{"description":"Pensil dipakai untuk menulis.","emoji":"🎒","visual":"🎒 ✏️ 📏","time":10,"level":"Dasar","intro":"Pada materi ini, kamu akan mempelajari benda di tas sekolah melalui teks, contoh, dan latihan.","explanation":"Pensil dipakai untuk menulis. Penghapus menghilangkan tulisan pensil. Penggaris membantu membuat garis lurus dan mengukur panjang. Buku tulis menjadi tempat menulis. Tas membawa perlengkapan. Rautan meruncingkan ujung pensil.","tip":"Cocokkan benda dengan kegunaannya. Bayangkan kegiatan menulis di kelas.","example":"","words":[],"relatedWords":[],"wordEntry":null,"contentRelease":"expanded-lessons-2026-10","mediaStatus":"text-visual-only"},"questions":[{"id":"a1fff3fc-50a9-4e8d-8ae4-7ba9104b2a35","logicalKey":"sd-tambahan-alat-sekolah:0","kind":"practice","position":0,"prompt":"Benda untuk menulis adalah …","options":["Pensil","Tas","Penghapus"],"answer":0},{"id":"cf7f15a0-268e-4eb3-81a4-c61e7a24961b","logicalKey":"sd-tambahan-alat-sekolah:1","kind":"quiz","position":0,"prompt":"Tulisan pensil dapat dihilangkan dengan …","options":["Rautan","Penghapus","Tas"],"answer":1},{"id":"a3ab9087-3a61-4c1c-8b0e-e442ea76d0c7","logicalKey":"sd-tambahan-alat-sekolah:2","kind":"quiz","position":1,"prompt":"Alat untuk membuat garis lurus adalah …","options":["Tas","Penghapus","Penggaris"],"answer":2},{"id":"06ff792e-17b5-477f-87c6-c56c387a174d","logicalKey":"sd-tambahan-alat-sekolah:3","kind":"quiz","position":2,"prompt":"Tempat mencatat pelajaran adalah …","options":["Buku tulis","Rautan","Penggaris"],"answer":0},{"id":"15c77eac-c2b2-43fd-8e76-ece68663341e","logicalKey":"sd-tambahan-alat-sekolah:4","kind":"quiz","position":3,"prompt":"Perlengkapan sekolah dibawa dalam …","options":["Penghapus","Tas","Pensil"],"answer":1},{"id":"e5480e95-47d2-477b-8b47-f188e7c380d8","logicalKey":"sd-tambahan-alat-sekolah:5","kind":"quiz","position":4,"prompt":"Ujung pensil yang tumpul diruncingkan dengan …","options":["Buku tulis","Tas","Rautan"],"answer":2}]},{"id":"c8636dc2-6bff-4c55-817e-6030fc3dec55","slug":"sd-tambahan-tempat-umum","grade":"SD","aspect":"kosakata","title":"Tempat di sekitar rumah","data":{"description":"Sekolah adalah tempat belajar.","emoji":"🏫","visual":"🏫 📚 🛒","time":10,"level":"Dasar","intro":"Pada materi ini, kamu akan mempelajari tempat di sekitar rumah melalui teks, contoh, dan latihan.","explanation":"Sekolah adalah tempat belajar. Perpustakaan menyediakan buku untuk dibaca atau dipinjam. Pasar menjadi tempat jual beli. Puskesmas menyediakan pelayanan kesehatan. Taman adalah tempat menikmati tanaman dan ruang terbuka. Kantor pos melayani pengiriman surat.","tip":"Perhatikan kegiatan yang ingin dilakukan, lalu pilih tempat yang sesuai.","example":"","words":[],"relatedWords":[],"wordEntry":null,"contentRelease":"expanded-lessons-2026-10","mediaStatus":"text-visual-only"},"questions":[{"id":"07d1a870-9120-400f-8b51-b2b4e9f82d78","logicalKey":"sd-tambahan-tempat-umum:0","kind":"practice","position":0,"prompt":"Tempat belajar bersama teman dan guru adalah …","options":["Pasar","Sekolah","Kantor pos"],"answer":1},{"id":"b8679166-c347-45ef-8b36-8824e6665712","logicalKey":"sd-tambahan-tempat-umum:1","kind":"quiz","position":0,"prompt":"Tempat meminjam buku adalah …","options":["Pasar","Taman","Perpustakaan"],"answer":2},{"id":"3da670a3-ab77-48e8-8030-749567fd16d9","logicalKey":"sd-tambahan-tempat-umum:2","kind":"quiz","position":1,"prompt":"Tempat membeli sayur dari pedagang adalah …","options":["Pasar","Kantor pos","Perpustakaan"],"answer":0},{"id":"73ccf978-ccb3-44de-8cd7-cd394773b043","logicalKey":"sd-tambahan-tempat-umum:3","kind":"quiz","position":2,"prompt":"Tempat memperoleh pelayanan kesehatan adalah …","options":["Taman","Puskesmas","Pasar"],"answer":1},{"id":"e03dc2eb-f230-442a-8309-99bd06fd9ffa","logicalKey":"sd-tambahan-tempat-umum:4","kind":"quiz","position":3,"prompt":"Tempat menikmati tanaman di ruang terbuka adalah …","options":["Kantor pos","Puskesmas","Taman"],"answer":2},{"id":"1375f2d5-630b-4bee-8de4-26dabd5aeea4","logicalKey":"sd-tambahan-tempat-umum:5","kind":"quiz","position":4,"prompt":"Tempat mengirim surat adalah …","options":["Kantor pos","Taman","Sekolah"],"answer":0}]},{"id":"46742ba5-fef9-42ea-8154-88a6bc118eac","slug":"sd-tambahan-kegiatan-pagi","grade":"SD","aspect":"kalimat","title":"Kalimat kegiatan pagi","data":{"description":"Kalimat menjelaskan siapa dan apa yang dilakukan.","emoji":"🧒","visual":"🧒 🪥 🎒","time":10,"level":"Dasar","intro":"Pada materi ini, kamu akan mempelajari kalimat kegiatan pagi melalui teks, contoh, dan latihan.","explanation":"Kalimat menjelaskan siapa dan apa yang dilakukan. Dalam “Dina menyikat gigi”, Dina adalah pelaku dan menyikat adalah kegiatan. Dalam “Bima membawa tas”, benda yang dibawa adalah tas. “Ibu memasak di dapur” memberi informasi tempat. “Ayah membaca pada pagi hari” memberi informasi waktu.","tip":"Tandai siapa, kegiatan, benda, tempat, dan waktu dengan warna berbeda.","example":"","words":[],"relatedWords":[],"wordEntry":null,"contentRelease":"expanded-lessons-2026-10","mediaStatus":"text-visual-only"},"questions":[{"id":"9ab1d50e-c302-4cb4-8b30-72b658951984","logicalKey":"sd-tambahan-kegiatan-pagi:0","kind":"practice","position":0,"prompt":"“Dina menyikat gigi.” Siapa pelakunya?","options":["Gigi","Tas","Dina"],"answer":2},{"id":"dc6d3e3d-b1c4-4e48-8560-0b091e0779d8","logicalKey":"sd-tambahan-kegiatan-pagi:1","kind":"quiz","position":0,"prompt":"“Dina menyikat gigi.” Apa kegiatannya?","options":["Menyikat","Membawa","Membaca"],"answer":0},{"id":"66cb1d17-74a3-4929-8b65-fda8c86c45a5","logicalKey":"sd-tambahan-kegiatan-pagi:2","kind":"quiz","position":1,"prompt":"“Bima membawa tas.” Apa yang dibawa?","options":["Buku","Tas","Gigi"],"answer":1},{"id":"8dcd055b-531e-4aea-8e6f-ca88c64abca8","logicalKey":"sd-tambahan-kegiatan-pagi:3","kind":"quiz","position":2,"prompt":"“Ibu memasak di dapur.” Di mana ibu memasak?","options":["Di taman","Di sekolah","Di dapur"],"answer":2},{"id":"ba12360e-9b41-40f3-860e-48940fb73d2a","logicalKey":"sd-tambahan-kegiatan-pagi:4","kind":"quiz","position":3,"prompt":"“Ayah membaca pada pagi hari.” Kapan ayah membaca?","options":["Pagi hari","Malam hari","Sore hari"],"answer":0},{"id":"2aadf184-311d-4ebc-8597-d1e159114143","logicalKey":"sd-tambahan-kegiatan-pagi:5","kind":"quiz","position":4,"prompt":"Urutan kata yang menjadi kalimat jelas adalah …","options":["Tas Bima membawa.","Bima membawa tas.","Membawa tas Bima."],"answer":1}]},{"id":"f159a191-f8de-49d4-8b57-f97ddb5f4b0a","slug":"sd-tambahan-petunjuk-urutan","grade":"SD","aspect":"kalimat","title":"Mengikuti petunjuk berurutan","data":{"description":"Petunjuk menanam biji: pertama, isi pot dengan tanah.","emoji":"🌱","visual":"🌱 → 💧 → ☀️","time":10,"level":"Dasar","intro":"Pada materi ini, kamu akan mempelajari mengikuti petunjuk berurutan melalui teks, contoh, dan latihan.","explanation":"Petunjuk menanam biji: pertama, isi pot dengan tanah. Kedua, masukkan biji ke tanah. Ketiga, siram secukupnya. Terakhir, letakkan pot di tempat yang mendapat cahaya. Kata pertama, kedua, ketiga, dan terakhir menunjukkan urutan kegiatan.","tip":"Gambar empat kotak. Isi satu kegiatan pada setiap kotak, lalu hubungkan dengan panah.","example":"","words":[],"relatedWords":[],"wordEntry":null,"contentRelease":"expanded-lessons-2026-10","mediaStatus":"text-visual-only"},"questions":[{"id":"ae9c9a12-d73d-4978-879e-9e2b0540dcd2","logicalKey":"sd-tambahan-petunjuk-urutan:0","kind":"practice","position":0,"prompt":"Langkah pertama adalah …","options":["Mengisi pot dengan tanah","Menyiram biji","Meletakkan pot di tempat bercahaya"],"answer":0},{"id":"8962ffd9-3df3-430c-8789-4bd4d6414ba0","logicalKey":"sd-tambahan-petunjuk-urutan:1","kind":"quiz","position":0,"prompt":"Setelah pot berisi tanah, kita …","options":["Membuang pot","Memasukkan biji","Memetik buah"],"answer":1},{"id":"6363ee29-d6b4-40ad-8389-85ee05040284","logicalKey":"sd-tambahan-petunjuk-urutan:2","kind":"quiz","position":1,"prompt":"Langkah ketiga adalah …","options":["Memasukkan tanah","Memanen buah","Menyiram secukupnya"],"answer":2},{"id":"db8feb47-8689-4e4b-8a40-fca28182efd3","logicalKey":"sd-tambahan-petunjuk-urutan:3","kind":"quiz","position":2,"prompt":"Langkah terakhir adalah …","options":["Meletakkan pot di tempat bercahaya","Memasukkan biji","Mengisi pot dengan tanah"],"answer":0},{"id":"2f1f06ca-5913-4c92-8717-3b3c99cb0d8c","logicalKey":"sd-tambahan-petunjuk-urutan:4","kind":"quiz","position":3,"prompt":"Kata yang menunjukkan urutan adalah …","options":["Hijau","Pertama","Besar"],"answer":1},{"id":"cdc09d36-df32-4b80-86d5-7bd75a401ad6","logicalKey":"sd-tambahan-petunjuk-urutan:5","kind":"quiz","position":4,"prompt":"Kegiatan sebelum menyiram adalah …","options":["Memanen buah","Menyimpan pot di lemari","Memasukkan biji"],"answer":2}]},{"id":"71d37269-7bed-4e04-8b0f-12121da43200","slug":"sd-tambahan-bekal-dina","grade":"SD","aspect":"bacaan","title":"Bekal untuk Dina","data":{"description":"Pada Senin pagi, Dina menyiapkan bekal bersama ibu.","emoji":"🍱","visual":"🍱 🍚 🥕","time":10,"level":"Dasar","intro":"Pada materi ini, kamu akan mempelajari bekal untuk dina melalui teks, contoh, dan latihan.","explanation":"Pada Senin pagi, Dina menyiapkan bekal bersama ibu. Dina memasukkan nasi dan wortel ke kotak bekal. Ibu menambahkan telur. Dina membawa air putih dalam botol. Saat istirahat di sekolah, Dina makan bekalnya. Setelah makan, ia menutup kotak bekal dan memasukkannya kembali ke tas.","tip":"Baca satu kalimat setiap kali. Cari nama, hari, isi bekal, dan waktu makan.","example":"","words":[],"relatedWords":[],"wordEntry":null,"contentRelease":"expanded-lessons-2026-10","mediaStatus":"text-visual-only"},"questions":[{"id":"7a12b95d-3b4e-4990-8e8a-bf96430f9242","logicalKey":"sd-tambahan-bekal-dina:0","kind":"practice","position":0,"prompt":"Siapa yang menyiapkan bekal bersama ibu?","options":["Bima","Dina","Rani"],"answer":1},{"id":"f4907cfe-4f4d-41ac-85a8-eb6ecfcda550","logicalKey":"sd-tambahan-bekal-dina:1","kind":"quiz","position":0,"prompt":"Kapan bekal disiapkan?","options":["Selasa malam","Minggu sore","Senin pagi"],"answer":2},{"id":"ecb8f30c-7a5b-411b-8d8f-45a823867f21","logicalKey":"sd-tambahan-bekal-dina:2","kind":"quiz","position":1,"prompt":"Sayuran yang dimasukkan Dina adalah …","options":["Wortel","Bayam","Tomat"],"answer":0},{"id":"e1e25aa2-9f73-4563-898b-0e7cca78f3c3","logicalKey":"sd-tambahan-bekal-dina:3","kind":"quiz","position":2,"prompt":"Apa yang ditambahkan ibu?","options":["Roti","Telur","Ikan"],"answer":1},{"id":"c678bbd8-1d11-40fe-819e-e6c81ff164a0","logicalKey":"sd-tambahan-bekal-dina:4","kind":"quiz","position":3,"prompt":"Apa minuman yang dibawa Dina?","options":["Susu","Jus","Air putih"],"answer":2},{"id":"d220b779-ae67-4412-8e85-a980eb600a49","logicalKey":"sd-tambahan-bekal-dina:5","kind":"quiz","position":4,"prompt":"Kapan Dina makan bekal?","options":["Saat istirahat di sekolah","Sebelum tidur","Saat menyiapkan bekal"],"answer":0}]},{"id":"029cbd73-000b-4c62-8d9c-56c58a05f57a","slug":"sd-tambahan-buku-kembali","grade":"SD","aspect":"bacaan","title":"Mengembalikan buku tepat waktu","data":{"description":"Raka meminjam buku cerita pada hari Rabu.","emoji":"📚","visual":"📚 📅 🤝","time":10,"level":"Dasar","intro":"Pada materi ini, kamu akan mempelajari mengembalikan buku tepat waktu melalui teks, contoh, dan latihan.","explanation":"Raka meminjam buku cerita pada hari Rabu. Petugas meminta buku dikembalikan pada hari Jumat. Raka membaca buku di rumah dan menjaga halamannya tetap bersih. Pada Jumat pagi, Raka memasukkan buku ke tas. Ia menyerahkannya kepada petugas perpustakaan. Raka senang karena mengembalikan buku tepat waktu.","tip":"Susun kejadian: meminjam, membaca, membawa, lalu mengembalikan.","example":"","words":[],"relatedWords":[],"wordEntry":null,"contentRelease":"expanded-lessons-2026-10","mediaStatus":"text-visual-only"},"questions":[{"id":"f306c105-8162-4147-8d9f-78f4d2cfd066","logicalKey":"sd-tambahan-buku-kembali:0","kind":"practice","position":0,"prompt":"Siapa yang meminjam buku?","options":["Dina","Petugas","Raka"],"answer":2},{"id":"cd69f38f-66cd-4d6f-8146-65d20fb9a15e","logicalKey":"sd-tambahan-buku-kembali:1","kind":"quiz","position":0,"prompt":"Hari peminjaman buku adalah …","options":["Rabu","Jumat","Senin"],"answer":0},{"id":"0cd1a41f-23bc-4e2a-82f4-31f230d72ac3","logicalKey":"sd-tambahan-buku-kembali:2","kind":"quiz","position":1,"prompt":"Buku harus dikembalikan pada …","options":["Kamis","Jumat","Minggu"],"answer":1},{"id":"023689c5-3252-480d-8a24-05debc2d41a1","logicalKey":"sd-tambahan-buku-kembali:3","kind":"quiz","position":2,"prompt":"Raka membaca buku di …","options":["Pasar","Halaman sekolah","Rumah"],"answer":2},{"id":"cf9930dd-9a71-4508-8c89-381e0359aab6","logicalKey":"sd-tambahan-buku-kembali:4","kind":"quiz","position":3,"prompt":"Bagaimana Raka merawat buku?","options":["Menjaga halaman tetap bersih","Mencoret semua halaman","Merobek sampul"],"answer":0},{"id":"ea28bfe6-f99e-4528-88e6-63e37048ab05","logicalKey":"sd-tambahan-buku-kembali:5","kind":"quiz","position":4,"prompt":"Buku dikembalikan kepada …","options":["Pedagang pasar","Petugas perpustakaan","Teman di rumah"],"answer":1}]},{"id":"300d5e10-416d-4eb4-8c01-0613ccb517d9","slug":"sd-tambahan-kelompok-benda","grade":"SD","aspect":"akademik","title":"Menghitung kelompok benda","data":{"description":"Perkalian dapat berarti penjumlahan berulang.","emoji":"🍎🍎","visual":"🍎🍎 | 🍎🍎 | 🍎🍎","time":10,"level":"Dasar","intro":"Pada materi ini, kamu akan mempelajari menghitung kelompok benda melalui teks, contoh, dan latihan.","explanation":"Perkalian dapat berarti penjumlahan berulang. Tiga kelompok berisi dua apel menjadi 2 + 2 + 2 = 6 apel. Dua kelompok berisi empat pensil menjadi 4 + 4 = 8 pensil. Pembagian sama rata membagi benda dengan jumlah yang sama: enam apel dibagi kepada tiga anak menghasilkan dua apel per anak.","tip":"Gambar kelompoknya dahulu. Hitung isi setiap kelompok dengan teliti.","example":"","words":[],"relatedWords":[],"wordEntry":null,"contentRelease":"expanded-lessons-2026-10","mediaStatus":"text-visual-only"},"questions":[{"id":"245bbb40-aa2a-4563-8a29-f2d2a1559310","logicalKey":"sd-tambahan-kelompok-benda:0","kind":"practice","position":0,"prompt":"Tiga kelompok berisi dua apel berjumlah …","options":["6 apel","5 apel","8 apel"],"answer":0},{"id":"d8dcab28-6b5c-4898-8ea0-0a116e190202","logicalKey":"sd-tambahan-kelompok-benda:1","kind":"quiz","position":0,"prompt":"Dua kelompok berisi empat pensil berjumlah …","options":["6 pensil","8 pensil","4 pensil"],"answer":1},{"id":"ff143143-5484-425e-8d37-c6ac8af6d7db","logicalKey":"sd-tambahan-kelompok-benda:2","kind":"quiz","position":1,"prompt":"4 + 4 + 4 sama dengan …","options":["8","16","12"],"answer":2},{"id":"a4cdd478-1f93-4cd2-8e41-d70f464ac21d","logicalKey":"sd-tambahan-kelompok-benda:3","kind":"quiz","position":2,"prompt":"Enam apel dibagi rata kepada tiga anak. Tiap anak mendapat …","options":["2 apel","3 apel","6 apel"],"answer":0},{"id":"d113afcb-bf11-43f0-8bfd-e3c3dded0c09","logicalKey":"sd-tambahan-kelompok-benda:4","kind":"quiz","position":3,"prompt":"Delapan pensil dibagi rata ke dua kotak. Tiap kotak berisi …","options":["2 pensil","4 pensil","6 pensil"],"answer":1},{"id":"70a8fbe9-4a80-44c6-8f34-b11fa7c296eb","logicalKey":"sd-tambahan-kelompok-benda:5","kind":"quiz","position":4,"prompt":"Lima kelompok masing-masing berisi satu buku berjumlah …","options":["6 buku","10 buku","5 buku"],"answer":2}]},{"id":"828464d7-3618-4053-826a-9a0a796868f6","slug":"sd-tambahan-panjang-dan-waktu","grade":"SD","aspect":"akademik","title":"Membaca panjang dan waktu","data":{"description":"Panjang benda dapat diukur dalam sentimeter (cm).","emoji":"📏","visual":"📏 🕒","time":10,"level":"Dasar","intro":"Pada materi ini, kamu akan mempelajari membaca panjang dan waktu melalui teks, contoh, dan latihan.","explanation":"Panjang benda dapat diukur dalam sentimeter (cm). Pada penggaris, letakkan awal benda di angka nol. Benda dari angka 0 sampai 8 memiliki panjang 8 cm. Satu jam sama dengan 60 menit. Dari pukul 07.00 ke 08.00 berlalu satu jam. Bandingkan ukuran dengan satuan yang sama.","tip":"Pisahkan soal panjang dari soal waktu. Tulis satuan pada setiap jawaban.","example":"","words":[],"relatedWords":[],"wordEntry":null,"contentRelease":"expanded-lessons-2026-10","mediaStatus":"text-visual-only"},"questions":[{"id":"612b3d10-4ce8-4bf6-867c-38a64296095d","logicalKey":"sd-tambahan-panjang-dan-waktu:0","kind":"practice","position":0,"prompt":"Benda dari angka 0 sampai 8 pada penggaris panjangnya …","options":["0 cm","8 cm","16 cm"],"answer":1},{"id":"e311de5b-088b-41cc-8cde-be9ed25a78e1","logicalKey":"sd-tambahan-panjang-dan-waktu:1","kind":"quiz","position":0,"prompt":"Satuan panjang dalam materi ini adalah …","options":["Menit","Jam","Sentimeter"],"answer":2},{"id":"53a3a3ec-9e17-402d-8c6f-dc394a33ed88","logicalKey":"sd-tambahan-panjang-dan-waktu:2","kind":"quiz","position":1,"prompt":"Satu jam sama dengan …","options":["60 menit","30 menit","100 menit"],"answer":0},{"id":"4ce213c0-6bc7-46ac-8469-128bbc81f1ac","logicalKey":"sd-tambahan-panjang-dan-waktu:3","kind":"quiz","position":2,"prompt":"Dari pukul 07.00 sampai 08.00 berlalu …","options":["2 jam","1 jam","3 jam"],"answer":1},{"id":"7e8104f7-ed6d-4a03-8e1c-5dfb77d74140","logicalKey":"sd-tambahan-panjang-dan-waktu:4","kind":"quiz","position":3,"prompt":"Pita 12 cm dibanding pita 9 cm adalah …","options":["Lebih pendek","Sama panjang","Lebih panjang"],"answer":2},{"id":"2ac85bb0-2692-4e76-8aab-80a1e0d6ad7c","logicalKey":"sd-tambahan-panjang-dan-waktu:5","kind":"quiz","position":4,"prompt":"Selisih panjang pita 12 cm dan 9 cm adalah …","options":["3 cm","21 cm","9 cm"],"answer":0}]},{"id":"87c4f860-b112-405e-88ac-0c0fc89aa9e3","slug":"smp-tambahan-lingkungan","grade":"SMP","aspect":"kosakata","title":"Kosakata menjaga lingkungan","data":{"description":"Sampah organik berasal dari bahan yang dapat terurai secara alami, misalnya sisa sayur.","emoji":"♻️","visual":"♻️ 🌿 🗑️","time":12,"level":"Menengah","intro":"Pada materi ini, kamu akan mempelajari kosakata menjaga lingkungan melalui teks, contoh, dan latihan.","explanation":"Sampah organik berasal dari bahan yang dapat terurai secara alami, misalnya sisa sayur. Kompos adalah pupuk dari penguraian bahan organik. Daur ulang mengolah bahan bekas menjadi bahan atau produk yang dapat digunakan kembali. Residu adalah sisa yang belum dapat diolah melalui proses yang tersedia. Konservasi berarti upaya pelestarian. Hemat berarti menggunakan sesuatu secukupnya.","tip":"Hubungkan istilah dengan contoh kegiatan di rumah atau sekolah.","example":"","words":[],"relatedWords":[],"wordEntry":null,"contentRelease":"expanded-lessons-2026-10","mediaStatus":"text-visual-only"},"questions":[{"id":"ed3a95f9-7008-4d65-8590-4d18f96e5770","logicalKey":"smp-tambahan-lingkungan:0","kind":"practice","position":0,"prompt":"Sisa sayur termasuk contoh sampah …","options":["Logam","Kaca","Organik"],"answer":2},{"id":"aeac8dda-bd33-43f9-8c10-12c606de257b","logicalKey":"smp-tambahan-lingkungan:1","kind":"quiz","position":0,"prompt":"Pupuk hasil penguraian bahan organik disebut …","options":["Kompos","Residu","Plastik"],"answer":0},{"id":"02bb0697-b4af-410c-8ca0-1714d63ebe03","logicalKey":"smp-tambahan-lingkungan:2","kind":"quiz","position":1,"prompt":"Mengolah kertas bekas menjadi kertas baru disebut …","options":["Penimbunan","Daur ulang","Pembakaran"],"answer":1},{"id":"79c3d3ec-e8e6-45a7-8efa-299505c079bf","logicalKey":"smp-tambahan-lingkungan:3","kind":"quiz","position":2,"prompt":"Sisa yang belum bisa diolah melalui proses tersedia disebut …","options":["Kompos","Konservasi","Residu"],"answer":2},{"id":"707112f7-4803-49a8-8749-a71b201b6d00","logicalKey":"smp-tambahan-lingkungan:4","kind":"quiz","position":3,"prompt":"Konservasi berarti …","options":["Upaya pelestarian","Penggunaan berlebihan","Pembuangan sembarangan"],"answer":0},{"id":"686f662f-c7d8-4394-89f2-986fe1f3991d","logicalKey":"smp-tambahan-lingkungan:5","kind":"quiz","position":4,"prompt":"Menggunakan air secukupnya merupakan tindakan …","options":["Boros","Hemat","Merusak"],"answer":1}]},{"id":"8efc84ad-3d4a-436b-866a-3ae2651b1030","slug":"smp-tambahan-informasi-digital","grade":"SMP","aspect":"kosakata","title":"Mengenali informasi digital","data":{"description":"Sumber adalah asal informasi.","emoji":"📱","visual":"📱 🔎 📝","time":12,"level":"Menengah","intro":"Pada materi ini, kamu akan mempelajari mengenali informasi digital melalui teks, contoh, dan latihan.","explanation":"Sumber adalah asal informasi. Fakta adalah pernyataan yang dapat diperiksa kebenarannya. Opini adalah pendapat atau penilaian. Verifikasi berarti memeriksa kebenaran. Judul merangkum topik dan perlu dibaca bersama isi. Tanggal terbit menunjukkan kapan informasi diterbitkan; tanggal membantu kita memeriksa apakah informasi masih relevan.","tip":"Periksa sumber, isi, bukti, dan tanggal. Jangan menyimpulkan hanya dari judul.","example":"","words":[],"relatedWords":[],"wordEntry":null,"contentRelease":"expanded-lessons-2026-10","mediaStatus":"text-visual-only"},"questions":[{"id":"5f733c5d-c050-467e-8606-9881dffa8cf0","logicalKey":"smp-tambahan-informasi-digital:0","kind":"practice","position":0,"prompt":"Asal suatu informasi disebut …","options":["Sumber","Opini","Judul"],"answer":0},{"id":"5343c8c8-2a28-4a8f-8b6f-83dcb4967de5","logicalKey":"smp-tambahan-informasi-digital:1","kind":"quiz","position":0,"prompt":"Pernyataan yang dapat diperiksa kebenarannya disebut …","options":["Selera","Fakta","Dugaan tanpa bukti"],"answer":1},{"id":"8054f526-6935-42d8-85d8-62107e6e8ceb","logicalKey":"smp-tambahan-informasi-digital:2","kind":"quiz","position":1,"prompt":"“Menurut saya, buku itu menarik” merupakan …","options":["Tanggal terbit","Sumber","Opini"],"answer":2},{"id":"6db42e5b-a37b-4c9d-8010-56fdf5d1523d","logicalKey":"smp-tambahan-informasi-digital:3","kind":"quiz","position":2,"prompt":"Memeriksa kebenaran informasi disebut …","options":["Verifikasi","Dekorasi","Duplikasi"],"answer":0},{"id":"eb267285-208a-4ff1-8608-2f5b23be2c73","logicalKey":"smp-tambahan-informasi-digital:4","kind":"quiz","position":3,"prompt":"Saat membaca berita, judul sebaiknya …","options":["Dianggap selalu lengkap","Dibaca bersama isinya","Menggantikan semua bukti"],"answer":1},{"id":"0c94263a-5511-451d-85d3-62185b0a0c03","logicalKey":"smp-tambahan-informasi-digital:5","kind":"quiz","position":4,"prompt":"Tanggal terbit membantu mengetahui …","options":["Jumlah pembaca pasti","Kebenaran semua kalimat","Kapan informasi diterbitkan"],"answer":2}]},{"id":"db442e17-4052-49cb-8136-6583c414580c","slug":"smp-tambahan-sebab-akibat","grade":"SMP","aspect":"kalimat","title":"Menghubungkan sebab dan akibat","data":{"description":"Sebab menjelaskan alasan, sedangkan akibat menjelaskan hasilnya.","emoji":"🌧️","visual":"🌧️ → 🌱","time":12,"level":"Menengah","intro":"Pada materi ini, kamu akan mempelajari menghubungkan sebab dan akibat melalui teks, contoh, dan latihan.","explanation":"Sebab menjelaskan alasan, sedangkan akibat menjelaskan hasilnya. “Tanaman layu karena tidak disiram” menyatakan sebab setelah karena. “Hujan turun sehingga halaman basah” menyatakan akibat setelah sehingga. “Dina membawa payung agar tidak kehujanan” menyatakan tujuan setelah agar. Hubungan antargagasan harus masuk akal.","tip":"Tanyakan “mengapa?” untuk sebab dan “apa hasilnya?” untuk akibat.","example":"","words":[],"relatedWords":[],"wordEntry":null,"contentRelease":"expanded-lessons-2026-10","mediaStatus":"text-visual-only"},"questions":[{"id":"320e8b85-7c5b-48e4-8930-b978b5611192","logicalKey":"smp-tambahan-sebab-akibat:0","kind":"practice","position":0,"prompt":"Dalam “Tanaman layu karena tidak disiram”, sebabnya adalah …","options":["Tanaman layu","Tidak disiram","Daun hijau"],"answer":1},{"id":"446a305e-6639-4935-80bd-ed3585e27bbd","logicalKey":"smp-tambahan-sebab-akibat:1","kind":"quiz","position":0,"prompt":"Dalam “Hujan turun sehingga halaman basah”, akibatnya adalah …","options":["Hujan turun","Awan putih","Halaman basah"],"answer":2},{"id":"c3432226-9e65-4ba2-8123-841f1190ce43","logicalKey":"smp-tambahan-sebab-akibat:2","kind":"quiz","position":1,"prompt":"Kata penghubung sebab adalah …","options":["Karena","Tetapi","Dan"],"answer":0},{"id":"076bcc72-597a-4361-80ea-7806b7d3f0a9","logicalKey":"smp-tambahan-sebab-akibat:3","kind":"quiz","position":2,"prompt":"Kata “agar” pada kalimat payung menunjukkan …","options":["Pertentangan","Tujuan","Urutan waktu"],"answer":1},{"id":"f017a3e2-955c-4179-8367-3e629764e780","logicalKey":"smp-tambahan-sebab-akibat:4","kind":"quiz","position":3,"prompt":"Hubungan sebab-akibat yang masuk akal adalah …","options":["Lampu mati karena buku tebal.","Lampu mati karena tas baru.","Lampu mati karena listrik padam."],"answer":2},{"id":"f273267a-d227-47ab-8cd9-1c6c4c4ff2eb","logicalKey":"smp-tambahan-sebab-akibat:5","kind":"quiz","position":4,"prompt":"“Rani belajar teratur sehingga lebih siap.” Rani lebih siap merupakan …","options":["Akibat","Sebab","Tempat"],"answer":0}]},{"id":"7df420f5-d4dc-4984-8f0b-3a1da659cc6d","slug":"smp-tambahan-kalimat-efektif","grade":"SMP","aspect":"kalimat","title":"Menyusun kalimat efektif","data":{"description":"Kalimat efektif menyampaikan gagasan dengan jelas dan tidak berlebihan.","emoji":"📝","visual":"📝 ✂️","time":12,"level":"Menengah","intro":"Pada materi ini, kamu akan mempelajari menyusun kalimat efektif melalui teks, contoh, dan latihan.","explanation":"Kalimat efektif menyampaikan gagasan dengan jelas dan tidak berlebihan. “Para siswa-siswa” berlebihan karena para sudah menunjukkan banyak; gunakan “Para siswa”. “Naik ke atas” dapat disederhanakan menjadi “Naik”. “Dina membaca buku di perpustakaan” jelas pelaku dan kegiatannya. Kata ganti harus memiliki rujukan yang jelas.","tip":"Hapus kata yang mengulang makna, lalu periksa apakah gagasan tetap lengkap.","example":"","words":[],"relatedWords":[],"wordEntry":null,"contentRelease":"expanded-lessons-2026-10","mediaStatus":"text-visual-only"},"questions":[{"id":"9c81867f-ea65-435e-8419-1748f27a3312","logicalKey":"smp-tambahan-kalimat-efektif:0","kind":"practice","position":0,"prompt":"Perbaikan “Para siswa-siswa belajar” adalah …","options":["Para para siswa belajar.","Siswa para siswa belajar.","Para siswa belajar."],"answer":2},{"id":"1d503b44-3f6f-4a03-8b8f-f3564f520998","logicalKey":"smp-tambahan-kalimat-efektif:1","kind":"quiz","position":0,"prompt":"Ungkapan yang lebih hemat adalah …","options":["Naik","Naik ke atas atas","Naik naik ke atas"],"answer":0},{"id":"c5131651-5db6-4fd8-8ae0-d271bd395fb8","logicalKey":"smp-tambahan-kalimat-efektif:2","kind":"quiz","position":1,"prompt":"Pelaku dalam “Dina membaca buku di perpustakaan” adalah …","options":["Buku","Dina","Perpustakaan"],"answer":1},{"id":"d187643d-a526-4dcf-8d77-94b060b748ba","logicalKey":"smp-tambahan-kalimat-efektif:3","kind":"quiz","position":2,"prompt":"Kalimat yang paling jelas adalah …","options":["Raka buku yang.","Menata yang buku.","Raka menata buku."],"answer":2},{"id":"83cb026b-0138-4b5a-8dd2-c223a80d18c7","logicalKey":"smp-tambahan-kalimat-efektif:4","kind":"quiz","position":3,"prompt":"Kalimat efektif sebaiknya …","options":["Jelas dan tidak berlebihan","Selalu sangat panjang","Mengulang semua kata"],"answer":0},{"id":"2c8aba71-12b0-4a9d-8b19-b5506386a6d1","logicalKey":"smp-tambahan-kalimat-efektif:5","kind":"quiz","position":4,"prompt":"Kata ganti “ia” dalam paragraf harus …","options":["Merujuk semua benda sekaligus","Memiliki rujukan jelas","Selalu dihapus"],"answer":1}]},{"id":"8077cd34-ac0c-42b2-8845-092f6e5d3641","slug":"smp-tambahan-bank-sampah","grade":"SMP","aspect":"bacaan","title":"Membaca laporan bank sampah","data":{"description":"Kelas VII membuka bank sampah pada Jumat.","emoji":"♻️","visual":"♻️ 📊","time":12,"level":"Menengah","intro":"Pada materi ini, kamu akan mempelajari membaca laporan bank sampah melalui teks, contoh, dan latihan.","explanation":"Kelas VII membuka bank sampah pada Jumat. Siswa memilah kertas dan botol plastik sebelum penimbangan. Minggu pertama terkumpul 12 kg kertas dan 8 kg botol plastik. Hasil penjualan disimpan untuk membeli bibit tanaman. Ketua kelas mencatat berat sampah agar perubahan jumlah dapat dibandingkan setiap minggu.","tip":"Bedakan kegiatan, data angka, dan tujuan program.","example":"","words":[],"relatedWords":[],"wordEntry":null,"contentRelease":"expanded-lessons-2026-10","mediaStatus":"text-visual-only"},"questions":[{"id":"eab2a905-1978-4287-83bb-7c3192cbb6ce","logicalKey":"smp-tambahan-bank-sampah:0","kind":"practice","position":0,"prompt":"Program bank sampah dimulai pada …","options":["Jumat","Senin","Minggu"],"answer":0},{"id":"b5608ca6-d765-4a7c-861d-72cff460779a","logicalKey":"smp-tambahan-bank-sampah:1","kind":"quiz","position":0,"prompt":"Sebelum ditimbang, sampah …","options":["Dibakar","Dipilah","Dicampur dengan makanan"],"answer":1},{"id":"1db61adf-1c6b-40fb-84d4-68c757a35ea0","logicalKey":"smp-tambahan-bank-sampah:2","kind":"quiz","position":1,"prompt":"Kertas yang terkumpul minggu pertama sebanyak …","options":["8 kg","20 kg","12 kg"],"answer":2},{"id":"d8d80deb-b00e-4d59-85d8-41fd16680aea","logicalKey":"smp-tambahan-bank-sampah:3","kind":"quiz","position":2,"prompt":"Hasil penjualan digunakan untuk …","options":["Membeli bibit tanaman","Membeli mainan","Membayar tiket rekreasi"],"answer":0},{"id":"b1f454ce-d366-48db-8f6d-5eadc93a0dc0","logicalKey":"smp-tambahan-bank-sampah:4","kind":"quiz","position":3,"prompt":"Tujuan mencatat berat sampah adalah …","options":["Mengganti kegiatan memilah","Membandingkan jumlah setiap minggu","Menghapus hasil penjualan"],"answer":1},{"id":"1c2ca672-ad48-4e3e-82e0-e820465adc81","logicalKey":"smp-tambahan-bank-sampah:5","kind":"quiz","position":4,"prompt":"Gagasan utama bacaan adalah …","options":["Cara membuat botol plastik","Jadwal libur sekolah","Pelaksanaan bank sampah kelas VII"],"answer":2}]},{"id":"04293187-e271-4af3-80a2-888cb0516321","slug":"smp-tambahan-pengumuman-kunjungan","grade":"SMP","aspect":"bacaan","title":"Memahami pengumuman kunjungan","data":{"description":"Pengumuman: Kelas VIII akan mengunjungi museum pada Sabtu, 18 Mei.","emoji":"🏛️","visual":"🏛️ 📅 🚌","time":12,"level":"Menengah","intro":"Pada materi ini, kamu akan mempelajari memahami pengumuman kunjungan melalui teks, contoh, dan latihan.","explanation":"Pengumuman: Kelas VIII akan mengunjungi museum pada Sabtu, 18 Mei. Peserta berkumpul di sekolah pukul 07.30. Bus berangkat pukul 08.00 dan kembali ke sekolah pukul 13.00. Peserta membawa bekal dan alat tulis. Formulir izin orang tua dikumpulkan paling lambat Kamis, 16 Mei. Pertanyaan disampaikan kepada wali kelas.","tip":"Tandai jadwal berkumpul, berangkat, kembali, dan batas pengumpulan izin.","example":"","words":[],"relatedWords":[],"wordEntry":null,"contentRelease":"expanded-lessons-2026-10","mediaStatus":"text-visual-only"},"questions":[{"id":"8349a134-df3f-434a-874b-b338b9649911","logicalKey":"smp-tambahan-pengumuman-kunjungan:0","kind":"practice","position":0,"prompt":"Tujuan kunjungan kelas VIII adalah …","options":["Pasar","Museum","Pelabuhan"],"answer":1},{"id":"8a5514e4-9dae-4966-8e82-e53319182857","logicalKey":"smp-tambahan-pengumuman-kunjungan:1","kind":"quiz","position":0,"prompt":"Peserta berkumpul pukul …","options":["08.00","13.00","07.30"],"answer":2},{"id":"6d8606aa-737f-44fb-8a48-f6c7368e07cd","logicalKey":"smp-tambahan-pengumuman-kunjungan:2","kind":"quiz","position":1,"prompt":"Bus berangkat pukul …","options":["08.00","07.30","13.00"],"answer":0},{"id":"0f68e329-ebed-4489-80af-ba7ce97022ca","logicalKey":"smp-tambahan-pengumuman-kunjungan:3","kind":"quiz","position":2,"prompt":"Batas pengumpulan formulir izin adalah …","options":["Sabtu, 18 Mei","Kamis, 16 Mei","Minggu, 19 Mei"],"answer":1},{"id":"7c51764c-1261-40ba-85d2-3e000a1fb98d","logicalKey":"smp-tambahan-pengumuman-kunjungan:4","kind":"quiz","position":3,"prompt":"Peserta diminta membawa …","options":["Bibit dan sekop","Bola dan raket","Bekal dan alat tulis"],"answer":2},{"id":"790ce2b1-92b8-4be9-8646-964bccc3d934","logicalKey":"smp-tambahan-pengumuman-kunjungan:5","kind":"quiz","position":4,"prompt":"Pertanyaan tentang kunjungan disampaikan kepada …","options":["Wali kelas","Petugas pasar","Sopir kendaraan lain"],"answer":0}]},{"id":"d9d1a150-f3ab-4e31-8a9b-e45b2e7055cd","slug":"smp-tambahan-rasio","grade":"SMP","aspect":"akademik","title":"Memahami perbandingan","data":{"description":"Minuman dibuat dengan perbandingan sirup dan air 2 : 3.","emoji":"🥤","visual":"🥤 2 : 3","time":12,"level":"Menengah","intro":"Pada materi ini, kamu akan mempelajari memahami perbandingan melalui teks, contoh, dan latihan.","explanation":"Minuman dibuat dengan perbandingan sirup dan air 2 : 3. Artinya setiap 2 bagian sirup dipasangkan dengan 3 bagian air. Totalnya 5 bagian. Jika ukuran resep dilipatgandakan, kedua jumlah dikalikan faktor yang sama. Untuk 4 gelas sirup diperlukan 6 gelas air; untuk 10 gelas campuran diperlukan 4 gelas sirup dan 6 gelas air.","tip":"Buat dua kolom: sirup dan air. Kalikan keduanya dengan bilangan yang sama.","example":"","words":[],"relatedWords":[],"wordEntry":null,"contentRelease":"expanded-lessons-2026-10","mediaStatus":"text-visual-only"},"questions":[{"id":"af756f7b-bb2b-43ae-8eb1-e6a7fff75093","logicalKey":"smp-tambahan-rasio:0","kind":"practice","position":0,"prompt":"Perbandingan sirup terhadap air adalah …","options":["3 : 2","2 : 5","2 : 3"],"answer":2},{"id":"ab98847d-8932-493f-815b-e5f64a58c08e","logicalKey":"smp-tambahan-rasio:1","kind":"quiz","position":0,"prompt":"Total bagian dalam resep adalah …","options":["5","6","1"],"answer":0},{"id":"df5f8263-1090-4339-892a-fab7fe875550","logicalKey":"smp-tambahan-rasio:2","kind":"quiz","position":1,"prompt":"Untuk 4 gelas sirup diperlukan air sebanyak …","options":["4 gelas","6 gelas","3 gelas"],"answer":1},{"id":"19d24f9f-b0ec-491c-8fb3-06b1632d327e","logicalKey":"smp-tambahan-rasio:3","kind":"quiz","position":2,"prompt":"Untuk 6 gelas sirup diperlukan air sebanyak …","options":["6 gelas","12 gelas","9 gelas"],"answer":2},{"id":"0f3e5719-445f-4776-80dd-265574c06537","logicalKey":"smp-tambahan-rasio:4","kind":"quiz","position":3,"prompt":"Dalam 10 gelas campuran, jumlah sirup adalah …","options":["4 gelas","5 gelas","6 gelas"],"answer":0},{"id":"12436104-d9c0-4ae7-8859-5d3021d94ce4","logicalKey":"smp-tambahan-rasio:5","kind":"quiz","position":4,"prompt":"Perbandingan yang setara dengan 2 : 3 adalah …","options":["4 : 5","8 : 12","6 : 8"],"answer":1}]},{"id":"4853de5d-beba-4e4a-85b7-afb40bdb30a1","slug":"smp-tambahan-persentase","grade":"SMP","aspect":"akademik","title":"Persentase dan potongan harga","data":{"description":"Persen berarti per seratus.","emoji":"💯","visual":"💯 🏷️","time":12,"level":"Menengah","intro":"Pada materi ini, kamu akan mempelajari persentase dan potongan harga melalui teks, contoh, dan latihan.","explanation":"Persen berarti per seratus. 25% sama dengan 25/100 atau 1/4. Untuk mencari 20% dari 50, hitung 20/100 × 50 = 10. Diskon mengurangi harga awal. Barang Rp100.000 dengan diskon 20% mendapat potongan Rp20.000, sehingga dibayar Rp80.000.","tip":"Pisahkan nilai potongan dari harga yang dibayar: harga awal dikurangi potongan.","example":"","words":[],"relatedWords":[],"wordEntry":null,"contentRelease":"expanded-lessons-2026-10","mediaStatus":"text-visual-only"},"questions":[{"id":"5870bfd0-d199-4609-8856-24ceef14317a","logicalKey":"smp-tambahan-persentase:0","kind":"practice","position":0,"prompt":"Persen berarti …","options":["Per seratus","Per sepuluh","Per seribu"],"answer":0},{"id":"280e5430-85c3-48ab-861c-c84932039db1","logicalKey":"smp-tambahan-persentase:1","kind":"quiz","position":0,"prompt":"25% sama dengan pecahan …","options":["1/2","1/4","3/4"],"answer":1},{"id":"d8b131fa-d2df-4a1d-8187-7cd5329d10f2","logicalKey":"smp-tambahan-persentase:2","kind":"quiz","position":1,"prompt":"20% dari 50 adalah …","options":["20","25","10"],"answer":2},{"id":"c9d6dbe6-01b2-4bc9-8e47-24849db364bf","logicalKey":"smp-tambahan-persentase:3","kind":"quiz","position":2,"prompt":"Diskon 20% dari Rp100.000 adalah …","options":["Rp20.000","Rp80.000","Rp120.000"],"answer":0},{"id":"824d3b86-6214-439b-82b4-fc904a68c2d1","logicalKey":"smp-tambahan-persentase:4","kind":"quiz","position":3,"prompt":"Harga Rp100.000 setelah diskon 20% adalah …","options":["Rp20.000","Rp80.000","Rp120.000"],"answer":1},{"id":"c9c325f0-7732-4461-8639-35476aab5753","logicalKey":"smp-tambahan-persentase:5","kind":"quiz","position":4,"prompt":"50% dari 40 siswa adalah …","options":["10 siswa","30 siswa","20 siswa"],"answer":2}]},{"id":"b4a87d06-77c8-4625-8abd-887afc6c3736","slug":"sma-tambahan-penelitian","grade":"SMA","aspect":"kosakata","title":"Kosakata penelitian sederhana","data":{"description":"Hipotesis adalah dugaan sementara yang dapat diuji.","emoji":"🔎","visual":"🔎 📋 📊","time":15,"level":"Lanjutan","intro":"Pada materi ini, kamu akan mempelajari kosakata penelitian sederhana melalui teks, contoh, dan latihan.","explanation":"Hipotesis adalah dugaan sementara yang dapat diuji. Variabel adalah hal yang dapat memiliki nilai berbeda. Sampel adalah bagian populasi yang diteliti; populasi adalah keseluruhan kelompok sasaran. Data adalah informasi yang dikumpulkan. Kesimpulan merangkum hasil berdasarkan data dan harus memperhatikan batas penelitian.","tip":"Hubungkan setiap istilah dengan tahap penelitian: merencanakan, mengumpulkan, menganalisis, menyimpulkan.","example":"","words":[],"relatedWords":[],"wordEntry":null,"contentRelease":"expanded-lessons-2026-10","mediaStatus":"text-visual-only"},"questions":[{"id":"a125c32e-bd59-45d8-8a2a-efb339805fcd","logicalKey":"sma-tambahan-penelitian:0","kind":"practice","position":0,"prompt":"Dugaan sementara yang dapat diuji disebut …","options":["Kesimpulan akhir","Hipotesis","Populasi"],"answer":1},{"id":"c6335ebd-3012-49f2-87d9-c902fcf370ac","logicalKey":"sma-tambahan-penelitian:1","kind":"quiz","position":0,"prompt":"Hal yang dapat memiliki nilai berbeda disebut …","options":["Daftar pustaka","Judul","Variabel"],"answer":2},{"id":"6d52de94-5d75-47f2-873b-d0398005b536","logicalKey":"sma-tambahan-penelitian:2","kind":"quiz","position":1,"prompt":"Bagian populasi yang diteliti disebut …","options":["Sampel","Seluruh populasi","Kesimpulan"],"answer":0},{"id":"6a7d04e6-fedc-4615-89ea-edd1bcd12627","logicalKey":"sma-tambahan-penelitian:3","kind":"quiz","position":2,"prompt":"Keseluruhan kelompok sasaran disebut …","options":["Sampel","Populasi","Hipotesis"],"answer":1},{"id":"c6d4bdec-e463-46f1-89c7-2d4457a0d381","logicalKey":"sma-tambahan-penelitian:4","kind":"quiz","position":3,"prompt":"Informasi yang dikumpulkan dalam penelitian disebut …","options":["Selera","Dekorasi","Data"],"answer":2},{"id":"fa7fc04a-030d-491a-8a22-82836a0acef0","logicalKey":"sma-tambahan-penelitian:5","kind":"quiz","position":4,"prompt":"Kesimpulan penelitian seharusnya didasarkan pada …","options":["Data dan batas penelitian","Keinginan peneliti saja","Judul saja"],"answer":0}]},{"id":"64644823-3e62-4be2-8117-725c3a4db976","slug":"sma-tambahan-argumentasi","grade":"SMA","aspect":"kosakata","title":"Kosakata argumentasi","data":{"description":"Klaim adalah pernyataan yang diajukan untuk diterima pembaca.","emoji":"💬","visual":"💬 📚 ⚖️","time":15,"level":"Lanjutan","intro":"Pada materi ini, kamu akan mempelajari kosakata argumentasi melalui teks, contoh, dan latihan.","explanation":"Klaim adalah pernyataan yang diajukan untuk diterima pembaca. Bukti adalah informasi yang mendukung klaim. Alasan menjelaskan hubungan bukti dengan klaim. Sanggahan menanggapi kelemahan argumen. Relevan berarti berkaitan dengan persoalan. Kredibel berarti layak dipercaya setelah sumber dan dasar informasinya diperiksa.","tip":"Pisahkan apa yang dinyatakan, bukti pendukung, dan alasan hubungan keduanya.","example":"","words":[],"relatedWords":[],"wordEntry":null,"contentRelease":"expanded-lessons-2026-10","mediaStatus":"text-visual-only"},"questions":[{"id":"71150577-956d-41f8-88cb-44d95d083938","logicalKey":"sma-tambahan-argumentasi:0","kind":"practice","position":0,"prompt":"Pernyataan yang diajukan kepada pembaca disebut …","options":["Daftar isi","Ilustrasi","Klaim"],"answer":2},{"id":"6363655c-eacb-4d1e-89fa-c5cc7af2c0e5","logicalKey":"sma-tambahan-argumentasi:1","kind":"quiz","position":0,"prompt":"Informasi pendukung klaim disebut …","options":["Bukti","Judul","Slogan"],"answer":0},{"id":"00db3059-c4f7-4a58-88b1-1deb63045f23","logicalKey":"sma-tambahan-argumentasi:2","kind":"quiz","position":1,"prompt":"Bagian yang menjelaskan hubungan bukti dan klaim adalah …","options":["Nama penulis","Alasan","Nomor halaman"],"answer":1},{"id":"b3940f08-925d-4293-84ed-1d6f42d15024","logicalKey":"sma-tambahan-argumentasi:3","kind":"quiz","position":2,"prompt":"Tanggapan terhadap kelemahan argumen disebut …","options":["Salinan","Ringkasan judul","Sanggahan"],"answer":2},{"id":"003427e6-6a4b-4212-8a50-1c6a1404463f","logicalKey":"sma-tambahan-argumentasi:4","kind":"quiz","position":3,"prompt":"Informasi relevan adalah informasi yang …","options":["Berkaitan dengan persoalan","Selalu paling panjang","Selalu paling populer"],"answer":0},{"id":"8fd9b1b6-315f-427d-8cbf-7416f819fc20","logicalKey":"sma-tambahan-argumentasi:5","kind":"quiz","position":4,"prompt":"Sumber kredibel dinilai melalui …","options":["Warna judulnya","Sumber dan dasar informasinya","Banyaknya emoji"],"answer":1}]},{"id":"2b4bd43f-19fe-4fb4-868c-1e23a91ab1a8","slug":"sma-tambahan-hubungan-logis","grade":"SMA","aspect":"kalimat","title":"Hubungan logis antarkalimat","data":{"description":"Penghubung antarkalimat membantu pembaca mengikuti gagasan.","emoji":"📝","visual":"📝 ↔️","time":15,"level":"Lanjutan","intro":"Pada materi ini, kamu akan mempelajari hubungan logis antarkalimat melalui teks, contoh, dan latihan.","explanation":"Penghubung antarkalimat membantu pembaca mengikuti gagasan. “Namun” menyatakan pertentangan. “Oleh karena itu” menyatakan akibat atau simpulan dari uraian sebelumnya. “Selain itu” menambah informasi. “Sebagai contoh” memperkenalkan contoh. “Dengan kata lain” menyatakan kembali gagasan. Penghubung harus sesuai hubungan makna.","tip":"Baca dua kalimat tanpa penghubung dahulu. Tentukan apakah isinya bertentangan, bertambah, atau menjadi akibat.","example":"","words":[],"relatedWords":[],"wordEntry":null,"contentRelease":"expanded-lessons-2026-10","mediaStatus":"text-visual-only"},"questions":[{"id":"671c4aa9-fca4-411f-8c83-bd4a980a57ca","logicalKey":"sma-tambahan-hubungan-logis:0","kind":"practice","position":0,"prompt":"Penghubung untuk pertentangan adalah …","options":["Namun","Selain itu","Sebagai contoh"],"answer":0},{"id":"f2b55736-2664-439b-8a9b-b9af1b75f1df","logicalKey":"sma-tambahan-hubungan-logis:1","kind":"quiz","position":0,"prompt":"Penghubung untuk tambahan informasi adalah …","options":["Namun","Selain itu","Sebaliknya"],"answer":1},{"id":"079428e0-6be8-434f-8562-3953ef1b6092","logicalKey":"sma-tambahan-hubungan-logis:2","kind":"quiz","position":1,"prompt":"“Oleh karena itu” menunjukkan …","options":["Contoh terpisah","Nama tempat","Akibat atau simpulan"],"answer":2},{"id":"befb8cdf-b851-410b-8718-c469b94956de","logicalKey":"sma-tambahan-hubungan-logis:3","kind":"quiz","position":2,"prompt":"Untuk memperkenalkan contoh, gunakan …","options":["Sebagai contoh","Namun","Sebaliknya"],"answer":0},{"id":"c3cd7232-8b1b-4e72-8133-d7077195677e","logicalKey":"sma-tambahan-hubungan-logis:4","kind":"quiz","position":3,"prompt":"“Dengan kata lain” digunakan untuk …","options":["Menambah tokoh","Menyatakan kembali gagasan","Menghapus bukti"],"answer":1},{"id":"236c453b-da75-449c-8d1a-c34931e145d3","logicalKey":"sma-tambahan-hubungan-logis:5","kind":"quiz","position":4,"prompt":"“Hujan sangat lebat. …, pertandingan ditunda.” Penghubung yang sesuai adalah …","options":["Sebagai contoh","Sebaliknya","Oleh karena itu"],"answer":2}]},{"id":"9ada46fe-1272-4bd7-8c2b-39d116da39e0","slug":"sma-tambahan-kutipan-parafrasa","grade":"SMA","aspect":"kalimat","title":"Membuat parafrasa yang setia","data":{"description":"Parafrasa menyampaikan gagasan sumber dengan susunan kata sendiri tanpa mengubah makna.","emoji":"📖","visual":"📖 → 📝","time":15,"level":"Lanjutan","intro":"Pada materi ini, kamu akan mempelajari membuat parafrasa yang setia melalui teks, contoh, dan latihan.","explanation":"Parafrasa menyampaikan gagasan sumber dengan susunan kata sendiri tanpa mengubah makna. Sumber tetap dicantumkan. Pernyataan “Sebagian siswa memilih belajar pagi” tidak sama dengan “Semua siswa memilih belajar pagi”. Kata sebagian, mungkin, dan dapat menunjukkan batas klaim. Kutipan langsung mempertahankan kata sumber dan memakai tanda kutip.","tip":"Periksa siapa, jumlah, waktu, dan tingkat kepastian sebelum dan sesudah memparafrasa.","example":"","words":[],"relatedWords":[],"wordEntry":null,"contentRelease":"expanded-lessons-2026-10","mediaStatus":"text-visual-only"},"questions":[{"id":"b0e5185b-0e82-48bb-8440-dbbb4d4e8173","logicalKey":"sma-tambahan-kutipan-parafrasa:0","kind":"practice","position":0,"prompt":"Parafrasa menggunakan …","options":["Kata acak tanpa makna","Susunan kata sendiri dengan makna tetap","Makna yang berlawanan"],"answer":1},{"id":"5bc5f0c9-48bb-4119-8e1e-a8682fa69933","logicalKey":"sma-tambahan-kutipan-parafrasa:1","kind":"quiz","position":0,"prompt":"Setelah melakukan parafrasa, sumber …","options":["Selalu dihapus","Diganti nama sendiri","Tetap dicantumkan"],"answer":2},{"id":"b3e0bebc-8835-4adb-838d-149aa93291ea","logicalKey":"sma-tambahan-kutipan-parafrasa:2","kind":"quiz","position":1,"prompt":"Parafrasa tepat untuk “Sebagian siswa memilih belajar pagi” adalah …","options":["Beberapa siswa lebih memilih belajar pada pagi hari.","Semua siswa hanya belajar pagi.","Tidak ada siswa belajar pagi."],"answer":0},{"id":"d69edc98-f2a1-433b-89d4-00494217b914","logicalKey":"sma-tambahan-kutipan-parafrasa:3","kind":"quiz","position":2,"prompt":"Mengubah “mungkin meningkat” menjadi “pasti meningkat” berarti …","options":["Mempertahankan makna sepenuhnya","Mengubah tingkat kepastian","Hanya mengganti tanda baca"],"answer":1},{"id":"c7e47c8f-9a87-46f9-8e62-ef9d2498695a","logicalKey":"sma-tambahan-kutipan-parafrasa:4","kind":"quiz","position":3,"prompt":"Kutipan langsung mempertahankan …","options":["Pendapat pembaca saja","Kesimpulan baru","Kata sumber"],"answer":2},{"id":"4795af1a-d14f-4b1c-8128-03ce22fd93af","logicalKey":"sma-tambahan-kutipan-parafrasa:5","kind":"quiz","position":4,"prompt":"Kata “sebagian” membatasi …","options":["Cakupan jumlah yang dimaksud","Warna tulisan","Nama penulis"],"answer":0}]},{"id":"02cb19e2-c0b7-4663-8672-02ba2a2adbd5","slug":"sma-tambahan-survei-perpustakaan","grade":"SMA","aspect":"bacaan","title":"Menilai kesimpulan survei","data":{"description":"Tim literasi menanyakan kebiasaan membaca kepada 40 anggota klub buku.","emoji":"📋","visual":"📋 40 → 30","time":15,"level":"Lanjutan","intro":"Pada materi ini, kamu akan mempelajari menilai kesimpulan survei melalui teks, contoh, dan latihan.","explanation":"Tim literasi menanyakan kebiasaan membaca kepada 40 anggota klub buku. Sebanyak 30 orang menyatakan membaca sedikitnya tiga kali seminggu. Tim menyimpulkan bahwa kebiasaan itu umum di antara responden klub buku. Survei belum mencakup seluruh siswa sekolah. Karena anggota klub mungkin lebih menyukai membaca, hasil ini belum cukup untuk menggambarkan semua siswa.","tip":"Cari siapa respondennya dan siapa yang dibicarakan dalam kesimpulan. Keduanya harus sesuai.","example":"","words":[],"relatedWords":[],"wordEntry":null,"contentRelease":"expanded-lessons-2026-10","mediaStatus":"text-visual-only"},"questions":[{"id":"54e00705-e42e-4e2f-83d9-a9ab23a53b10","logicalKey":"sma-tambahan-survei-perpustakaan:0","kind":"practice","position":0,"prompt":"Responden survei adalah …","options":["Semua siswa sekolah","30 guru","40 anggota klub buku"],"answer":2},{"id":"16ad4652-5ef2-4d99-82ae-ea9a1b3ed5f7","logicalKey":"sma-tambahan-survei-perpustakaan:1","kind":"quiz","position":0,"prompt":"Jumlah responden yang membaca sedikitnya tiga kali seminggu adalah …","options":["30 orang","40 orang","10 orang"],"answer":0},{"id":"448e153d-495d-44c1-8330-ce690bb511dd","logicalKey":"sma-tambahan-survei-perpustakaan:2","kind":"quiz","position":1,"prompt":"Kesimpulan yang didukung bacaan adalah …","options":["Semua siswa sekolah membaca setiap hari.","Kebiasaan tersebut umum di antara responden klub.","Tidak ada siswa yang jarang membaca."],"answer":1},{"id":"6aa6f737-5a57-4a89-8674-086a5e58af93","logicalKey":"sma-tambahan-survei-perpustakaan:3","kind":"quiz","position":2,"prompt":"Keterbatasan survei adalah …","options":["Tidak memiliki responden","Tidak mencatat jumlah","Belum mencakup seluruh siswa sekolah"],"answer":2},{"id":"8b2ab231-be5f-4a87-8f58-f241918dd8db","logicalKey":"sma-tambahan-survei-perpustakaan:4","kind":"quiz","position":3,"prompt":"Mengapa anggota klub dapat berbeda dari siswa lain?","options":["Mereka mungkin lebih menyukai membaca.","Mereka pasti tidak membaca.","Mereka selalu memiliki nilai sama."],"answer":0},{"id":"1922e85c-de34-4a5a-8c46-18e3842525fd","logicalKey":"sma-tambahan-survei-perpustakaan:5","kind":"quiz","position":4,"prompt":"Untuk menggambarkan sekolah lebih baik, survei perlu …","options":["Hanya anggota klub yang sama","Responden dari beragam kelompok siswa","Menghapus semua jawaban"],"answer":1}]},{"id":"a1468ef9-203b-4bd4-8502-8cab30539305","slug":"sma-tambahan-evaluasi-program","grade":"SMA","aspect":"bacaan","title":"Membaca evaluasi program sekolah","data":{"description":"Sekolah memasang tempat isi ulang air.","emoji":"💧","visual":"💧 📊 🏫","time":15,"level":"Lanjutan","intro":"Pada materi ini, kamu akan mempelajari membaca evaluasi program sekolah melalui teks, contoh, dan latihan.","explanation":"Sekolah memasang tempat isi ulang air. Pada pekan sebelum pemasangan, petugas menghitung 120 botol plastik di tempat sampah. Pada pekan setelahnya ditemukan 75 botol. Pada pekan kedua itu, satu tingkat kelas sedang mengikuti kegiatan di luar sekolah. Data menunjukkan jumlah botol berkurang, tetapi perubahan kehadiran juga mungkin berpengaruh. Evaluasi lanjutan perlu membandingkan pekan dengan jumlah siswa hadir yang serupa.","tip":"Bedakan hasil pengamatan dari penjelasan penyebab. Periksa faktor lain yang ikut berubah.","example":"","words":[],"relatedWords":[],"wordEntry":null,"contentRelease":"expanded-lessons-2026-10","mediaStatus":"text-visual-only"},"questions":[{"id":"8eef36fc-37bc-42ed-84af-bbb88806e6d9","logicalKey":"sma-tambahan-evaluasi-program:0","kind":"practice","position":0,"prompt":"Program yang dievaluasi adalah …","options":["Tempat isi ulang air","Perpustakaan baru","Lapangan olahraga"],"answer":0},{"id":"3e839fe4-6928-4f11-8bfc-1ef7d2af3314","logicalKey":"sma-tambahan-evaluasi-program:1","kind":"quiz","position":0,"prompt":"Jumlah botol sebelum pemasangan adalah …","options":["75","120","45"],"answer":1},{"id":"210fe72f-13a8-4b84-8a36-41f1e14b9ab5","logicalKey":"sma-tambahan-evaluasi-program:2","kind":"quiz","position":1,"prompt":"Jumlah botol setelah pemasangan adalah …","options":["120","195","75"],"answer":2},{"id":"12e6e15b-8315-4123-8e7b-90f5122d4aef","logicalKey":"sma-tambahan-evaluasi-program:3","kind":"quiz","position":2,"prompt":"Faktor lain yang berubah adalah …","options":["Jumlah siswa yang hadir","Warna botol saja","Nama sekolah"],"answer":0},{"id":"fdbe8fa1-ee4c-47ff-8efd-6542eccf164c","logicalKey":"sma-tambahan-evaluasi-program:4","kind":"quiz","position":3,"prompt":"Kesimpulan paling hati-hati adalah …","options":["Program pasti satu-satunya penyebab.","Jumlah botol turun, tetapi penyebabnya belum dapat dipastikan tunggal.","Jumlah botol tidak berubah."],"answer":1},{"id":"e35dd047-7335-4722-8785-71110527956e","logicalKey":"sma-tambahan-evaluasi-program:5","kind":"quiz","position":4,"prompt":"Perbandingan lanjutan sebaiknya menggunakan …","options":["Pekan tanpa data kehadiran","Hanya angka terbesar","Pekan dengan kehadiran siswa serupa"],"answer":2}]},{"id":"f6845a38-853b-4781-86dc-ac0cacf140ee","slug":"sma-tambahan-statistika","grade":"SMA","aspect":"akademik","title":"Rata-rata, median, dan rentang","data":{"description":"Data nilai lima latihan adalah 60, 70, 70, 80, dan 90.","emoji":"📊","visual":"📊 60 70 70 80 90","time":15,"level":"Lanjutan","intro":"Pada materi ini, kamu akan mempelajari rata-rata, median, dan rentang melalui teks, contoh, dan latihan.","explanation":"Data nilai lima latihan adalah 60, 70, 70, 80, dan 90. Rata-rata diperoleh dengan menjumlahkan semua nilai lalu membaginya dengan banyak data: 370 ÷ 5 = 74. Median adalah nilai tengah data terurut, yaitu 70. Modus adalah nilai paling sering muncul, yaitu 70. Rentang adalah nilai terbesar dikurangi terkecil: 90 − 60 = 30.","tip":"Urutkan data sebelum mencari median. Bedakan rata-rata, nilai tengah, dan nilai paling sering muncul.","example":"","words":[],"relatedWords":[],"wordEntry":null,"contentRelease":"expanded-lessons-2026-10","mediaStatus":"text-visual-only"},"questions":[{"id":"0e9e8ff9-368a-42af-8f6e-f46f0074cc33","logicalKey":"sma-tambahan-statistika:0","kind":"practice","position":0,"prompt":"Banyak data nilai pada contoh adalah …","options":["4","5","6"],"answer":1},{"id":"a5bed4e5-c0ea-4aa2-8d58-a31ecb2f625e","logicalKey":"sma-tambahan-statistika:1","kind":"quiz","position":0,"prompt":"Jumlah seluruh nilai adalah …","options":["350","390","370"],"answer":2},{"id":"22c95c64-06c7-4418-84cd-d217cb37504e","logicalKey":"sma-tambahan-statistika:2","kind":"quiz","position":1,"prompt":"Rata-rata nilai adalah …","options":["74","70","80"],"answer":0},{"id":"bb91a463-dbab-43f1-8fe8-4ff2aae2b7b0","logicalKey":"sma-tambahan-statistika:3","kind":"quiz","position":2,"prompt":"Median data adalah …","options":["74","70","80"],"answer":1},{"id":"9a9ae2b1-be58-428d-8b39-ec26e7d601e2","logicalKey":"sma-tambahan-statistika:4","kind":"quiz","position":3,"prompt":"Modus data adalah …","options":["60","90","70"],"answer":2},{"id":"4322253a-9ac3-47de-86e3-e05c8c058861","logicalKey":"sma-tambahan-statistika:5","kind":"quiz","position":4,"prompt":"Rentang data adalah …","options":["30","20","150"],"answer":0}]},{"id":"7b0241fb-501c-4af0-8b72-95c5672d59f3","slug":"sma-tambahan-fungsi-linear","grade":"SMA","aspect":"akademik","title":"Membaca hubungan linear","data":{"description":"Fungsi y = 2x + 3 memasangkan setiap nilai x dengan nilai y.","emoji":"📈","visual":"📈 y = 2x + 3","time":15,"level":"Lanjutan","intro":"Pada materi ini, kamu akan mempelajari membaca hubungan linear melalui teks, contoh, dan latihan.","explanation":"Fungsi y = 2x + 3 memasangkan setiap nilai x dengan nilai y. Jika x = 0 maka y = 3; jika x = 1 maka y = 5; jika x = 2 maka y = 7. Setiap x bertambah satu, y bertambah dua. Angka 2 adalah gradien, sedangkan 3 adalah nilai y saat x = 0. Untuk mencari x saat y diketahui, kurangi y dengan 3 lalu bagi dua.","tip":"Ganti x dengan angkanya, lakukan perkalian dahulu, lalu tambahkan tiga.","example":"","words":[],"relatedWords":[],"wordEntry":null,"contentRelease":"expanded-lessons-2026-10","mediaStatus":"text-visual-only"},"questions":[{"id":"2d43e345-9582-47b1-80d2-f3649e27309b","logicalKey":"sma-tambahan-fungsi-linear:0","kind":"practice","position":0,"prompt":"Pada y = 2x + 3, jika x = 0 maka y = …","options":["2","0","3"],"answer":2},{"id":"e40dbe4f-1b96-4cc0-8838-d6e0e60f1e62","logicalKey":"sma-tambahan-fungsi-linear:1","kind":"quiz","position":0,"prompt":"Jika x = 2 maka y = …","options":["7","5","9"],"answer":0},{"id":"b07eda0a-d6d2-4e17-8d89-ae48e0980358","logicalKey":"sma-tambahan-fungsi-linear:2","kind":"quiz","position":1,"prompt":"Jika x = 4 maka y = …","options":["8","11","14"],"answer":1},{"id":"9390ee20-28c9-4f10-8971-c2ec5af19ed5","logicalKey":"sma-tambahan-fungsi-linear:3","kind":"quiz","position":2,"prompt":"Setiap x bertambah satu, y bertambah …","options":["3","1","2"],"answer":2},{"id":"d55865d2-7af5-4e04-8841-8edebfd67853","logicalKey":"sma-tambahan-fungsi-linear:4","kind":"quiz","position":3,"prompt":"Gradien fungsi tersebut adalah …","options":["2","3","5"],"answer":0},{"id":"ecbd94a0-e719-4acd-85e9-1b984a972e3e","logicalKey":"sma-tambahan-fungsi-linear:5","kind":"quiz","position":4,"prompt":"Jika y = 13 maka x = …","options":["8","5","10"],"answer":1}]}]'::jsonb; item jsonb; q jsonb;
begin
 perform pg_advisory_xact_lock(hashtext('expanded-lessons-2026-10'));
 for item in select jsonb_array_elements(items) loop
  -- A rerun must never overwrite an admin's edited revision or add mixed question sets.
  if exists(select 1 from public.lessons where slug=item->>'slug') then continue; end if;
  insert into public.lessons(id,slug,revision,kind,grade,aspect,title,data,status)
   values((item->>'id')::uuid,item->>'slug',1,'lesson',item->>'grade',item->>'aspect',item->>'title',item->'data','published');
  for q in select jsonb_array_elements(item->'questions') loop
   insert into public.questions(id,logical_key,revision,kind,lesson_id,grade,aspect,position,format,prompt,options,data,status)
    values((q->>'id')::uuid,q->>'logicalKey',1,q->>'kind',(item->>'id')::uuid,item->>'grade',item->>'aspect',(q->>'position')::integer,'choice',q->>'prompt',q->'options','{}'::jsonb,'published');
   insert into private.answer_keys(question_id,answer) values((q->>'id')::uuid,q->'answer');
  end loop;
 end loop;
end; $release$;
commit;
